// #534912 (6a993d74959b605c0b534912) — «מסלול ביקורת» попытки у Super Admin (F-24, S-02 AC5). Кейсы SUP-006…SUP-009.
// /admin/support → меню строки «פעולות תמיכה עבור <имя>» → «מסלול ביקורת» → rpc/get_attempt_audit_trail
// {p_candidate_id, p_reason:"support"} → панель «מסלול ביקורת» (data-testid audit-trail-drawer), таблица «שלב / ניסיון N · <тег>», 7 строк.
// БЕЗ звонков, по ГОТОВЫМ данным 21.10 (проверены вручную, скриншоты .qa/screenshots/2026-10-21/534912-*.png):
//  - QA-534912-2110-AC2 (493832b7…) — ссылка не открывалась: заполнены только «יצירת קישור» и «תפוגה» (+48 ч);
//  - QA-C4-2110-D2 (08c67252) — завершённая попытка: «הפקת דוח» отдельно от «סיום»;
//  - QA-C6-2110-D2 (79e8f0b8) — сброс после сбоя: «ניסיון 2 · נוכחי» / «ניסיון 1 · אופס».
// Если данные ушли (сброс/очистка 90 дней) — подставить своих кандидатов через QA_534912_* (см. ниже); иначе тест падает «нет данных».
// Побочный эффект чтения: каждое открытие трассы с причиной пишет запись в журнал доступа SA (D-25) — это норма.
// PATCH-проверки (AC5) — только на приглашение QA-534912-2110-AC2 и только значением, равным текущему (no-op); ждём отказ 403.
// Админка — только десктоп (lessons L: телефон есть только у кандидата).
import { Locator, Page, Response } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openWithApi, Api } from '../support/api';

const HASH = '#534912 · #6a993d74959b605c0b534912';
const UNOPENED = process.env.QA_534912_UNOPENED_CANDIDATE || 'QA-534912-2110-AC2';
const COMPLETED = process.env.QA_534912_COMPLETED_CANDIDATE || 'QA-C4-2110-D2';
const RESET = process.env.QA_534912_RESET_CANDIDATE || 'QA-C6-2110-D2';

// Порядок строк и подписи — как в панели (AC1).
const STAGES = [
  ['link_created_at', 'יצירת קישור'],
  ['first_opened_at', 'כניסה ראשונה'],
  ['tech_check_started_at', 'תחילת בדיקה טכנית'],
  ['simulation_started_at', 'תחילת סימולציה'],
  ['simulation_ended_at', 'סיום'],
  ['report_generated_at', 'הפקת דוח'],
  ['expires_at', 'תפוגה'],
] as const;
type Field = (typeof STAGES)[number][0];
const LABEL = Object.fromEntries(STAGES) as Record<Field, string>;
const FOOTNOTE = 'שלב ריק עדיין לא התרחש. חותמות הזמן נרשמות אוטומטית ואינן ניתנות לעריכה.';
const SHOWN_TIME = /\d{1,2}[./]\d{1,2}[./]\d{2,4}.*\d{1,2}:\d{2}/;

type Invite = { id: string; status?: string } & Partial<Record<Field, string | null>>;
type Attempt = { id: string; invite_id: string; attempt_type: string; status: string; reset_at?: string | null };
type Trail = { invites: Invite[]; attempts: Attempt[]; support_actions?: unknown[] };

/** /admin/support (все даты) → меню строки кандидата → «מסלול ביקורת». Возвращает панель и ответ get_attempt_audit_trail. */
async function openTrail(admin: Page, name: string) {
  const api = await openWithApi(admin, '/admin/support');
  await expect(admin.getByRole('heading', { level: 1, name: 'תמיכה ותפעול' })).toBeVisible();
  // Таблица по умолчанию — 7 дней; данные от 21.10, поэтому «כל התאריכים» (фильтр данные не меняет).
  await admin.getByRole('combobox', { name: 'טווח תאריכים' }).selectOption({ label: 'כל התאריכים' });
  const row = admin.getByRole('row').filter({ hasText: name }).first();
  await expect(row, `нет строки «${name}» в /admin/support (все даты) — нет данных`).toBeVisible({ timeout: 30_000 });

  await row.getByRole('button', { name: `פעולות תמיכה עבור ${name}` }).click();
  const item = admin.getByRole('menuitem', { name: 'מסלול ביקורת', exact: true });
  await expect(item, 'в меню строки нет «מסלול ביקורת» (S-02 AC5, Figma 816:1183)').toBeVisible();

  const responsePromise = admin.waitForResponse((r: Response) => r.url().includes('/rest/v1/rpc/get_attempt_audit_trail') && r.request().method() === 'POST');
  await item.click();
  const res = await responsePromise;
  const body = res.request().postDataJSON() as { p_candidate_id: string; p_reason: string };
  expect(body.p_reason, 'доступ SA к трассе — с причиной (D-25)').toBe('support');
  expect(res.status(), await res.text()).toBe(200);
  const trail = (await res.json()) as Trail;

  const drawer = admin.getByTestId('audit-trail-drawer');
  await expect(drawer).toBeVisible();
  await expect(drawer.getByText(name).first()).toBeVisible();
  await expect(drawer.getByRole('heading', { name: 'חותמות זמן' })).toBeVisible();
  return { api, drawer, trail, candidateId: body.p_candidate_id };
}

/** Ячейка панели: строка этапа × колонка попытки (0 — первая колонка после «שלב», это текущая попытка). */
function cell(drawer: Locator, field: Field, column: number) {
  return drawer
    .getByRole('row')
    .filter({ has: drawer.page().getByRole('rowheader', { name: LABEL[field], exact: true }) })
    .getByRole('cell')
    .nth(column);
}

const currentInvite = (t: Trail) => t.invites[t.invites.length - 1];
const ms = (s: string | null | undefined) => (s ? Date.parse(s) : NaN);

test.describe(`Поддержка — מסלול ביקורת попытки (${HASH})`, () => {
  test(`неоткрытая ссылка: в меню есть «מסלול ביקורת», 7 этапов, заполнены только «יצירת קישור» и «תפוגה» (+48 ч), остальные «—», не 0 и не 1970 @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    const { drawer, trail } = await openTrail(admin, UNOPENED);

    // AC1: все 7 этапов в порядке; одна колонка — текущая попытка.
    await expect(drawer.locator('tbody').getByRole('rowheader')).toHaveText(STAGES.map(([, l]) => l));
    await expect(drawer.getByRole('columnheader')).toHaveText(['שלב', 'ניסיון 1 · נוכחי']);

    // AC2 — данные: ссылка не открывалась → пустые этапы null, попыток нет.
    expect(trail.invites, 'одно приглашение').toHaveLength(1);
    expect(trail.attempts, 'попыток нет').toEqual([]);
    const inv = currentInvite(trail);
    for (const f of ['first_opened_at', 'tech_check_started_at', 'simulation_started_at', 'simulation_ended_at', 'report_generated_at'] as const) {
      expect(inv[f] ?? null, `${f} у неоткрытой ссылки`).toBeNull();
    }
    expect(inv.link_created_at, 'link_created_at').toBeTruthy();
    expect(inv.expires_at, 'expires_at').toBeTruthy();
    // Срок ссылки — 2 дня (48 ч) от создания (допуск 1 мин).
    expect(Math.abs(ms(inv.expires_at) - ms(inv.link_created_at) - 48 * 3600_000), 'expires_at − link_created_at = 48 ч').toBeLessThanOrEqual(60_000);

    // AC2 — экран: пустые — «—», заполненные — дата и время; нигде нет 0 / 01.01.1970.
    for (const [f] of STAGES) {
      const c = cell(drawer, f, 0);
      if (f === 'link_created_at' || f === 'expires_at') {
        await expect(c, `${LABEL[f]} заполнена`).toHaveText(SHOWN_TIME);
      } else {
        await expect(c, `${LABEL[f]} пустая — «—»`).toHaveText('—');
      }
    }
    await expect(drawer.getByText(/1970/)).toHaveCount(0);
    await expect(drawer.getByText(FOOTNOTE, { exact: true })).toBeVisible();
  });

  test(`ручного изменения меток нет: в панели нет полей ввода, PATCH меток (business и admin) → 403 42501, трасса без причины → 400 reason_required @desktop ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    const { api: adminApi, drawer, trail, candidateId } = await openTrail(admin, UNOPENED);
    const inv = currentInvite(trail);

    // AC5 — экран: в панели нечего редактировать.
    await expect(drawer.locator('input, textarea, select, [contenteditable="true"]')).toHaveCount(0);
    await expect(drawer.getByRole('button', { name: /עריכ|לערוך|שינוי|עדכון/ })).toHaveCount(0);
    await expect(drawer.getByText(FOOTNOTE, { exact: true })).toBeVisible();

    // AC5 — сервер: прямая запись меток запрещена. Только приглашение QA-534912-2110-AC2, значение = текущему (no-op);
    // у этого приглашения нет попыток, поэтому PATCH attempts не затрагивает ни одной строки.
    const business = await asUser('business');
    const businessApi = await openWithApi(business, '/candidates');
    for (const [who, api] of [['business', businessApi], ['admin', adminApi]] as [string, Api][]) {
      const invRes = await api.patch(`candidate_invites?id=eq.${inv.id}`, { link_created_at: inv.link_created_at });
      expect(invRes.status(), `${who}: PATCH candidate_invites.link_created_at — ${await invRes.text()}`).toBe(403);
      expect((await invRes.json()).code).toBe('42501');

      const attRes = await api.patch(`attempts?invite_id=eq.${inv.id}`, { reset_at: null });
      expect(attRes.status(), `${who}: PATCH attempts — ${await attRes.text()}`).toBe(403);
      expect((await attRes.json()).code).toBe('42501');
    }

    // D-25: SA без причины трассу не получает.
    const noReason = await adminApi.rpc('get_attempt_audit_trail', { p_candidate_id: candidateId });
    expect(noReason.status(), await noReason.text()).toBe(400);
    expect(await noReason.text()).toContain('reason_required');

    // Метка не изменилась.
    const again = await adminApi.rpc('get_attempt_audit_trail', { p_candidate_id: candidateId, p_reason: 'support' });
    expect(again.status()).toBe(200);
    const after = currentInvite((await again.json()) as Trail);
    expect(after.link_created_at).toBe(inv.link_created_at);
  });

  test(`завершённая попытка: все 7 меток по порядку, «הפקת דוח» отдельно от «סיום» @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    const { drawer, trail } = await openTrail(admin, COMPLETED);
    const inv = currentInvite(trail);

    // AC1 — данные: все метки есть и идут по порядку жизненного цикла.
    for (const [f] of STAGES) expect(inv[f], `${f} у завершённой попытки (${COMPLETED}, QA_534912_COMPLETED_CANDIDATE)`).toBeTruthy();
    const chain: Field[] = ['link_created_at', 'first_opened_at', 'tech_check_started_at', 'simulation_started_at', 'simulation_ended_at', 'report_generated_at'];
    for (let i = 1; i < chain.length; i++) {
      expect(ms(inv[chain[i]]), `${chain[i - 1]} ≤ ${chain[i]}`).toBeGreaterThanOrEqual(ms(inv[chain[i - 1]]));
    }
    // Требование: время отчёта — отдельная метка, не равна концу звонка.
    expect(inv.report_generated_at, 'report_generated_at ≠ simulation_ended_at').not.toBe(inv.simulation_ended_at);
    expect(ms(inv.report_generated_at)).toBeGreaterThan(ms(inv.simulation_ended_at));

    // AC1 — экран: текущая попытка, все 7 строк заполнены.
    await expect(drawer.getByRole('columnheader').nth(1)).toHaveText(/^ניסיון \d+ · נוכחי$/);
    await expect(drawer.locator('tbody').getByRole('rowheader')).toHaveText(STAGES.map(([, l]) => l));
    for (const [f] of STAGES) await expect(cell(drawer, f, 0), `${LABEL[f]} заполнена`).toHaveText(SHOWN_TIME);
  });

  test(`сброшенная попытка: «ניסיון 2 · נוכחי» и «ניסיון 1 · אופס» рядом, метки старой сохранены, место остановки помечено @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const admin = await asUser('admin');
    const { drawer, trail } = await openTrail(admin, RESET);

    // AC4 — данные: два приглашения, у прежнего метки сохранены, его официальная попытка в статусе reset.
    expect(trail.invites, `два приглашения у ${RESET} (QA_534912_RESET_CANDIDATE)`).toHaveLength(2);
    const [old, cur] = trail.invites;
    for (const f of ['link_created_at', 'first_opened_at', 'tech_check_started_at', 'simulation_started_at'] as const) {
      expect(old[f], `прежняя попытка: ${f} сохранена`).toBeTruthy();
    }
    expect(cur.link_created_at).toBeTruthy();
    expect(
      trail.attempts.some((a) => a.invite_id === old.id && a.attempt_type === 'official' && a.status === 'reset'),
      'официальная попытка прежнего приглашения — reset',
    ).toBeTruthy();

    // AC4 — экран: колонки рядом, текущая первой; плашка о сбросе.
    await expect(drawer.getByRole('columnheader')).toHaveText(['שלב', 'ניסיון 2 · נוכחי', 'ניסיון 1 · אופס']);
    await expect(drawer.getByText('הניסיון הקודם אופס')).toBeVisible();
    await expect(cell(drawer, 'link_created_at', 1)).toHaveText(SHOWN_TIME);
    await expect(cell(drawer, 'simulation_started_at', 1)).toHaveText(SHOWN_TIME);
    await expect(cell(drawer, 'link_created_at', 0)).toHaveText(SHOWN_TIME);

    // AC3 — у прежней попытки последняя записанная метка помечена «הניסיון נעצר כאן».
    const lastFilled = (['link_created_at', 'first_opened_at', 'tech_check_started_at', 'simulation_started_at', 'simulation_ended_at', 'report_generated_at'] as Field[])
      .filter((f) => old[f])
      .at(-1)!;
    await expect(cell(drawer, lastFilled, 1).getByText(/^הניסיון נעצר כאן/)).toBeVisible();
    await expect(drawer.locator(`[data-invite-id="${old.id}"]`).getByText(/^הניסיון נעצר כאן/)).toHaveCount(1);
  });
});
